        last_name: 'MacDonald'
      }, {
        age: 29,
        first_name: 'Dick',
        last_name: 'Dunlap'
      }]
    };
  },
  methods: {
    getCellStyle(index, field) {
      // Стилі для всіх комірок, деякі комірки виділені
      const rowStyles = {
        2: {
          backgroundColor: '#f8d7da'
        } // Рядок повністю червоний (index 2)
      };
      const cellStyles = {
        '3_age': {
          backgroundColor: '#d1ecf1'
        },
        // Голуба комірка (вік Thor)
        '3_first_name': {
          backgroundColor: '#fff3cd'
        } // Жовта комірка (Thor)
      };
      const cellKey = `${index}_${field}`;
      if (rowStyles[index]) return rowStyles[index];
      if (cellStyles[cellKey]) return cellStyles[cellKey];
      return {
        backgroundColor: this.getRandomColor(index, field)
      };
    },
    getRandomColor(index, field) {
      // Випадкові кольори для всіх інших комірок (приклад — для навчання)
      const colors = ['#e2f0cb', '#c2f0f7', '#d4c2fc', '#fce1c2', '#e2c2f7'];
      const key = (index + field).length % colors.length;
      return colors[key];
    }
  }
};
